async function generateText(request,execution){
  const combined=AbortSignal.any([execution.signal,shutdown.signal]);checkAbort(combined);
  if(!Array.isArray(request.messages)||request.messages.some(m=>!['system','user'].includes(m.role)||typeof m.content!=='string'))fail('MEMORY_MODEL_INPUT');
  if(execution.scope)auxiliaryScopes.set(combined,execution.scope);
  const options={provider:'deepseek-official',model:request.model,maxTokens:request.max_tokens,system:request.messages.filter(m=>m.role==='system').map(m=>m.content).join('\n'),messages:request.messages.filter(m=>m.role==='user').map(m=>({role:'user',content:[{type:'text',text:m.content}]})),tools:[],signal:combined};
  let text='',finished=false,truncated=false;
  for await(const chunk of ctx.llm.stream(options)){
    checkAbort(combined);
    if(chunk.type==='tool-call-delta'||chunk.type==='block-start'&&chunk.blockType==='tool-call')fail('MEMORY_MODEL_TOOL_CALL');
    if(chunk.type==='text-delta'){text+=chunk.text;if(Buffer.byteLength(text)>256000)fail('MEMORY_MODEL_OUTPUT_LIMIT');}
    if(chunk.type==='finish'){
      if(!['stop','max-tokens'].includes(chunk.reason.kind))fail('MEMORY_MODEL_INCOMPLETE');
      finished=true;truncated=chunk.reason.kind==='max-tokens';
    }
  }
  checkAbort(combined);if(!finished||!text.trim())fail('MEMORY_MODEL_INCOMPLETE');
  // The native Profile interceptor owns the only ledger reservation. No
  // synthetic provider receipt or request id is manufactured here.
  return {text,model:request.model,truncated};
}
